                writer.WriteString("user_verification", userVerificationRawValue);
            }
            if (clientDeviceAuthnKey.VarVersionOption.IsSet)
                writer.WriteNumber("version", clientDeviceAuthnKey.VarVersionOption.Value!.Value);
        }
    }
}
